<script setup lang="ts">
import { useIamManage } from '../composables/useIamManage'
const {canManage,account}=useIamManage()
const page=ref(1),total=ref(0)
function searchRows(){page.value=1;load()}
import { onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import client from '../api/client'
import type { IamOptions } from '../api/iamTypes'
import TableActionButton from '../components/TableActionButton.vue'
const users=ref<any[]>([]),roles=ref<any[]>([]),departments=ref<any[]>([]),loading=ref(false),saving=ref(false),dialog=ref(false),search=ref(''),form=ref<any>({})
async function load(){loading.value=true;try{const [u,options]=await Promise.all([client.get('/users/',{params:{search:search.value,page:page.value,page_size:20}}),client.get<IamOptions>('/users/options/')]);users.value=u.data.results;total.value=u.data.count;roles.value=options.data.roles;departments.value=options.data.departments}catch{ElMessage.error('用户数据加载失败')}finally{loading.value=false}}
function canEdit(row:any){return canManage.value&&(account.value.is_superuser||(!row.is_superuser&&(row.roles||[]).every((id:string)=>(roles.value.find(role=>role.id===id)?.effective_permissions||[]).every((permission:string)=>account.value.permissions.includes(permission)))))}

function createUser(){form.value={username:'',password:'',first_name:'',last_name:'',email:'',phone:'',department:null,data_scope:'SELF',is_active:true,roles:[]};dialog.value=true}
function editUser(row:any){form.value={...row,password:'',roles:row.roles||[],data_scope:row.data_scope||'SELF'};dialog.value=true}
async function save(){if(!form.value.username)return ElMessage.warning('请输入用户名');if(!form.value.id&&!form.value.password)return ElMessage.warning('请输入初始密码');if(form.value.password&&form.value.password.length<12)return ElMessage.warning('用户密码至少为12位');saving.value=true;try{const payload={...form.value,data_scope:form.value.data_scope||'SELF'};if(!payload.password)delete payload.password;if(payload.id)await client.patch(`/users/${payload.id}/`,payload);else await client.post('/users/',payload);dialog.value=false;ElMessage.success(payload.id?'用户信息已更新':'用户创建成功');load()}catch(e:any){ElMessage.error(JSON.stringify(e.response?.data?.details||e.response?.data||'保存失败'))}finally{saving.value=false}}
async function toggle(row:any){try{await client.patch(`/users/${row.id}/`,{is_active:!row.is_active});ElMessage.success(row.is_active?'用户已停用':'用户已启用');load()}catch(e:any){ElMessage.error(JSON.stringify(e.response?.data||'操作失败'))}}
async function remove(row:any){try{await ElMessageBox.confirm(`确定删除用户“${row.username}”吗？删除后无法恢复。`,'删除用户',{confirmButtonText:'删除',cancelButtonText:'取消',type:'warning'});await client.delete(`/users/${row.id}/`);ElMessage.success('用户已删除');load()}catch(e:any){if(e==='cancel'||e==='close')return;ElMessage.error(e.response?.data?.details?.detail||e.response?.data?.detail||'删除失败')}}
const roleNames=(row:any)=>(row.roles||[]).map((id:string)=>roles.value.find(r=>r.id===id)?.name).filter(Boolean).join('、')||'未分配'
onMounted(load)
</script>
<template><section><div class="page-head"><div><h2 class="page-title">用户管理</h2><div class="page-subtitle">维护账号、部门归属、角色权限；访问按模块功能权限控制</div></div><el-button v-if="canManage" type="primary" @click="createUser">＋ 新增用户</el-button></div><el-card><div class="filters"><el-input v-model="search" clearable placeholder="搜索用户名、姓名或邮箱" @clear="searchRows" @keyup.enter="searchRows"><template #prefix>⌕</template></el-input><el-button @click="searchRows">查询</el-button><span>共 {{total}} 个用户</span></div><el-table v-loading="loading" :data="users" stripe><el-table-column label="用户" min-width="180"><template #default="s"><div class="user-cell"><div class="user-avatar">{{s.row.username.slice(0,1).toUpperCase()}}</div><div><b>{{s.row.username}}</b><span>{{[s.row.last_name,s.row.first_name].filter(Boolean).join('')||'未填写姓名'}}</span></div></div></template></el-table-column><el-table-column prop="department_name" label="所属部门" min-width="130"><template #default="s">{{s.row.department_name||'—'}}</template></el-table-column><el-table-column prop="email" label="邮箱" min-width="190"><template #default="s">{{s.row.email||'—'}}</template></el-table-column><el-table-column label="业务角色" min-width="170"><template #default="s">{{roleNames(s.row)}}</template></el-table-column><el-table-column label="账号状态" width="100"><template #default="s"><el-tag :type="s.row.is_active?'success':'info'">{{s.row.is_active?'正常':'已停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="205" fixed="right" align="center"><template #default="s"><div class="row-actions"><TableActionButton v-if="canEdit(s.row)" icon="edit" label="编辑" tone="primary" @click="editUser(s.row)"/><TableActionButton v-if="canEdit(s.row)" icon="toggle" :disabled="s.row.id===account.id" :label="s.row.is_active?'停用':'启用'" :tone="s.row.is_active?'warning':'success'" @click="toggle(s.row)"/><TableActionButton v-if="canEdit(s.row)" icon="delete" :disabled="s.row.id===account.id" label="删除" tone="danger" icon-only @click="remove(s.row)"/></div></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total, prev, pager, next" @current-change="load"/></el-card><el-dialog v-model="dialog" :title="form.id?'编辑用户':'新增用户'" width="680px"><el-alert v-if="form.id" title="留空密码表示不修改；输入新密码可同时完成密码重置。" type="info" :closable="false"/><el-form label-position="top" class="user-form"><div class="form-grid"><el-form-item label="用户名" required><el-input v-model="form.username" :disabled="!!form.id"/></el-form-item><el-form-item :label="form.id?'新密码':'初始密码'" :required="!form.id"><el-input v-model="form.password" type="password" show-password placeholder="至少12位，避免常见密码或纯数字"/></el-form-item><el-form-item label="姓"><el-input v-model="form.last_name"/></el-form-item><el-form-item label="名"><el-input v-model="form.first_name"/></el-form-item><el-form-item label="邮箱"><el-input v-model="form.email" type="email"/></el-form-item><el-form-item label="手机号码"><el-input v-model="form.phone"/></el-form-item><el-form-item label="所属部门"><el-select v-model="form.department" clearable style="width:100%"><el-option v-for="dept in departments" :key="dept.id" :label="dept.name+(dept.is_enabled?'':'（停用）')" :disabled="!dept.is_enabled&&dept.id!==form.department" :value="dept.id"/></el-select></el-form-item><el-form-item label="业务角色" class="wide"><el-select v-model="form.roles" multiple clearable style="width:100%"><el-option v-for="role in roles" :key="role.id" :label="role.name+(role.is_enabled?'':'（停用）')" :disabled="(!role.is_enabled&&!form.roles.includes(role.id))||(!account.is_superuser&&(role.is_system_role||role.effective_permissions.some((permission:string)=>!account.permissions.includes(permission))))" :value="role.id"/></el-select></el-form-item></div><div class="switch-row single"><div><b>启用账号</b><span>停用后将无法登录系统</span><el-switch v-model="form.is_active"/></div></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存用户</el-button></template></el-dialog></section></template>
<style scoped>.page-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px}.filters{display:flex;align-items:center;gap:10px;margin-bottom:16px}.filters .el-input{width:320px}.filters span{margin-left:auto;color:#7c8999;font-size:12px}.user-cell{display:flex;align-items:center;gap:11px}.user-avatar{width:34px;height:34px;border-radius:4px;background:#e8f0f8;color:#174b7a;display:grid;place-items:center;font-weight:700}.user-cell>div:last-child{display:flex;flex-direction:column}.user-cell b{font-size:13px}.user-cell span{font-size:11px;color:#8a95a4;margin-top:3px}.row-actions{display:flex;align-items:center;justify-content:center;gap:5px}.el-alert{margin-bottom:18px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 18px}.wide{grid-column:1/-1}.switch-row{display:grid;border:1px solid #e0e6ed;border-radius:5px}.switch-row>div{display:grid;grid-template-columns:1fr auto;align-items:center;padding:13px 16px}.switch-row b{font-size:13px}.switch-row span{font-size:11px;color:#8793a3;grid-row:2}.switch-row .el-switch{grid-row:1/3;grid-column:2}@media(max-width:700px){.form-grid{grid-template-columns:1fr}.wide{grid-column:auto}}
@media(max-width:700px){.grid{grid-template-columns:1fr}.permission-group{grid-template-columns:1fr;gap:10px}}
</style>
